using Microsoft.Data.SqlClient;using System;using System.Data;using System.Windows;using System.Windows.Controls;
namespace POSS{public partial class ProductPage:Page{private int selectedId=0;private readonly string connectionString=DatabaseConfig.ConnectionString;public ProductPage(){InitializeComponent();LoadProducts();}
private void LoadProducts(){try{using SqlConnection conn=new(connectionString);conn.Open();SqlDataAdapter da=new("SELECT Id,Barcode,Name,Price FROM [Table] ORDER BY Name",conn);DataTable dt=new();da.Fill(dt);ProductGrid.ItemsSource=dt.DefaultView;txtProductCount.Text=dt.Rows.Count+" 件";if(ProductGrid.Columns.Count>0)ProductGrid.Columns[0].Visibility=Visibility.Collapsed;}catch(Exception ex){MessageBox.Show(ex.Message);}}
private void btnAdd_Click(object sender,RoutedEventArgs e){try{if(string.IsNullOrWhiteSpace(txtBarcode.Text)||string.IsNullOrWhiteSpace(txtName.Text)||string.IsNullOrWhiteSpace(txtPrice.Text)){MessageBox.Show("すべて入力してください");return;}using SqlConnection conn=new(connectionString);conn.Open();SqlCommand cmd=new("INSERT INTO [Table](Barcode,Name,Price) VALUES(@Barcode,@Name,@Price)",conn);cmd.Parameters.AddWithValue("@Barcode",txtBarcode.Text);cmd.Parameters.AddWithValue("@Name",txtName.Text);cmd.Parameters.AddWithValue("@Price",Convert.ToInt32(txtPrice.Text));cmd.ExecuteNonQuery();MessageBox.Show("商品を追加しました");txtBarcode.Clear();txtName.Clear();txtPrice.Clear();selectedId=0;LoadProducts();}catch(Exception ex){MessageBox.Show(ex.Message);}}
private void ProductGrid_SelectionChanged(object sender,SelectionChangedEventArgs e){if(ProductGrid.SelectedItem==null)return;DataRowView row=(DataRowView)ProductGrid.SelectedItem;selectedId=Convert.ToInt32(row["Id"]);txtBarcode.Text=row["Barcode"].ToString();txtName.Text=row["Name"].ToString();txtPrice.Text=row["Price"].ToString();}
private void btnEdit_Click(object sender,RoutedEventArgs e){try{if(selectedId==0){MessageBox.Show("商品を選択してください");return;}using SqlConnection conn=new(connectionString);conn.Open();SqlCommand cmd=new("UPDATE [Table] SET Name=@Name,Price=@Price WHERE Id=@Id",conn);cmd.Parameters.AddWithValue("@Id",selectedId);cmd.Parameters.AddWithValue("@Name",txtName.Text);cmd.Parameters.AddWithValue("@Price",Convert.ToInt32(txtPrice.Text));cmd.ExecuteNonQuery();MessageBox.Show("更新しました");LoadProducts();}catch(Exception ex){MessageBox.Show(ex.Message);}}
private void btnDelete_Click(object sender,RoutedEventArgs e){try{if(ProductGrid.SelectedItem==null){MessageBox.Show("商品を選択してください");return;}DataRowView row=(DataRowView)ProductGrid.SelectedItem;int id=Convert.ToInt32(row["Id"]);if(MessageBox.Show("削除しますか？","確認",MessageBoxButton.YesNo,MessageBoxImage.Question)!=MessageBoxResult.Yes)return;using SqlConnection conn=new(connectionString);conn.Open();SqlCommand cmd=new("DELETE FROM [Table] WHERE Id=@Id",conn);cmd.Parameters.AddWithValue("@Id",id);cmd.ExecuteNonQuery();MessageBox.Show("削除しました");txtBarcode.Clear();txtName.Clear();txtPrice.Clear();selectedId=0;LoadProducts();}catch(Exception ex){MessageBox.Show(ex.Message);}}}}